package com.spaceagent.platform.project.infrastructure.persistence;
import com.fasterxml.jackson.databind.ObjectMapper;import com.spaceagent.platform.project.domain.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.*;import java.util.*;
@Repository @ConditionalOnProperty(prefix="platform",name="persistence",havingValue="postgres") public class PostgresProjectBlueprintRepository implements ProjectBlueprintRepository{
 private final JdbcTemplate j;private final ObjectMapper o;public PostgresProjectBlueprintRepository(JdbcTemplate j,ObjectMapper o){this.j=j;this.o=o;}public int nextVersion(String p){Integer v=j.queryForObject("SELECT COALESCE(MAX(version_number),0)+1 FROM platform_project_blueprints WHERE project_id=CAST(? AS UUID)",Integer.class,p);return v==null?1:v;}public void save(ProjectBlueprint b){try{j.update("INSERT INTO platform_project_blueprints(id,tenant_id,project_id,version_number,status,source,source_repository_id,generated_by_agent_id,generated_by_run_configuration_snapshot_id,created_by,confirmed_by,confirmed_at,document_json,created_at,updated_at) VALUES(CAST(? AS UUID),?,CAST(? AS UUID),?,?,?,CAST(? AS UUID),?,?,?,?,?,CAST(? AS JSONB),?,?) ON CONFLICT(id) DO UPDATE SET status=EXCLUDED.status,confirmed_by=EXCLUDED.confirmed_by,confirmed_at=EXCLUDED.confirmed_at,updated_at=EXCLUDED.updated_at",b.id(),b.tenantId(),b.projectId(),b.versionNumber(),b.status().name(),b.source().name(),b.sourceRepositoryId(),b.generatedByAgentId(),b.generatedByRunConfigurationSnapshotId(),b.createdBy(),b.confirmedBy(),ts(b.confirmedAt()),o.writeValueAsString(b.document()),Timestamp.from(b.createdAt()),Timestamp.from(b.updatedAt()));}catch(Exception e){throw new IllegalStateException(e);}}public Optional<ProjectBlueprint> findById(String id){return j.query("SELECT * FROM platform_project_blueprints WHERE id=CAST(? AS UUID)",this::map,id).stream().findFirst();}public List<ProjectBlueprint> findByProjectId(String p){return j.query("SELECT * FROM platform_project_blueprints WHERE project_id=CAST(? AS UUID) ORDER BY version_number",this::map,p);}public Optional<ProjectBlueprint> findConfirmed(String p){return j.query("SELECT * FROM platform_project_blueprints WHERE project_id=CAST(? AS UUID) AND status='CONFIRMED'",this::map,p).stream().findFirst();}private ProjectBlueprint map(ResultSet r,int n)throws SQLException{try{return new ProjectBlueprint(r.getString("id"),r.getString("tenant_id"),r.getString("project_id"),r.getInt("version_number"),ProjectBlueprintStatus.valueOf(r.getString("status")),ProjectBlueprintSource.valueOf(r.getString("source")),r.getString("source_repository_id"),r.getString("generated_by_agent_id"),r.getString("generated_by_run_configuration_snapshot_id"),r.getString("created_by"),r.getString("confirmed_by"),inst(r.getTimestamp("confirmed_at")),o.readValue(r.getString("document_json"),ProjectBlueprintDocument.class),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}catch(Exception e){throw new SQLException(e);}}private static Timestamp ts(java.time.Instant v){return v==null?null:Timestamp.from(v);}private static java.time.Instant inst(Timestamp v){return v==null?null:v.toInstant();}}
